#!/usr/bin/env python3
from __future__ import annotations
import json
from pathlib import Path
root=Path.cwd()
required=["data/deployment/release_certificate_postseal_validation_v59.json", "data/security/legal_speech_dataset_v58_freeze_v59.json", "data/search/music_search_production_policy_v59.json", "data/integration/authority_metadata_publication_expansion_v59.json", "data/audio/speech_governance_download_audit_hardening_v59.json", "data/site/operations_notification_closed_loop_v59.json", "data/admin/music_speech_review_center_v59.json", "data/ops/vps_preflight_v59.json", "data/development/next_upgrade_plan_v60.json", "backend/src/rest/ttsSttMusicV59Routes.ts", "frontend-sdk/ttsSttMusicClient.v59.ts", "webapp/components/MusicSpeechReviewCenterV59.tsx", "webapp/app/admin/music-speech/v59/page.tsx", "database/migrations/0055_tts_stt_music_v59.sql", "database/seeds/055_tts_stt_music_v59.sql", "database/seeds/055_production_postseal_validation_v59.generated.sql", "database/seeds/055_legal_speech_dataset_freeze_v59.generated.sql", "database/seeds/055_search_production_policy_v59.generated.sql", "database/seeds/055_authority_metadata_expansion_v59.generated.sql", "database/seeds/055_governance_download_hardening_v59.generated.sql", "database/seeds/055_operations_closed_loop_v59.generated.sql", "deploy/vps-tts-stt-v59.sh", "docs/tts_stt_music_v59.md", "docs/release_certificate_postseal_validation_v59.generated.md", "docs/legal_speech_dataset_v58_freeze_v59.generated.md", "docs/operations_notification_closed_loop_v59.generated.md", "docs/next_upgrade_plan_v60.md"]
